from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def regular_lines(values):
        if len(values) < 3:
            return None
        gaps = [values[i + 1] - values[i] for i in range(len(values) - 1)]
        if gaps[0] <= 1 or any(g != gaps[0] for g in gaps):
            return None
        return values

    candidates = []
    for color in range(10):
        rows = [r for r in range(h) if grid[r].count(color) / w >= 0.70]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) / h >= 0.70]
        rr, cc = regular_lines(rows), regular_lines(cols)
        if rr and cc:
            candidates.append((len(rr) * len(cc), color, rr, cc))

    if not candidates:
        return [[0]]

    _, rail, rows, cols = max(candidates)

    marked = [(i, j) for i, r in enumerate(rows) for j, c in enumerate(cols)
              if grid[r][c] != rail]
    if not marked:
        return [[rail]]

    rmin = min(i for i, _ in marked)
    rmax = max(i for i, _ in marked)
    cmin = min(j for _, j in marked)
    cmax = max(j for _, j in marked)
    rows = rows[rmin:rmax + 1]
    cols = cols[cmin:cmax + 1]

    interior = Counter(
        grid[r][c]
        for r in range(h) if r not in set(rows)
        for c in range(w) if c not in set(cols)
    )
    base = interior.most_common(1)[0][0] if interior else 0

    out = [[base for _ in range(len(cols) - 1)] for _ in range(len(rows) - 1)]
    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]
            ]
            if corners[0] != rail and all(x == corners[0] for x in corners):
                out[i][j] = corners[0]
    return out
